var out=[],seen={},m;

/* 1. SCDht / BTLM title anchors: hash-bearing links are direct, ordinary links stay as detail URLs. */
var are=/<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
while((m=are.exec(html))!==null){
    var attrs=String(m[1]||""),cls=attr(attrs,"class");
    if(!/(^|\s)title(\s|$)/i.test(cls))continue;
    var href=attr(attrs,"href"),title=attr(attrs,"title")||text(m[2]);
    var seg=html.substring(Math.max(0,m.index-500),Math.min(html.length,m.index+5000));
    add(out,seen,title,href,seg);
    if(out.length>=60)break;
}
if(out.length)return out;

/* 2. Heading anchors used by SCDht forks and compatible DHT search front-ends. */
var hre=/<h[234]\b[^>]*>[\s\S]*?<a\b([^>]*)>([\s\S]*?)<\/a>[\s\S]*?<\/h[234]>/gi;
while((m=hre.exec(html))!==null){
    var hattrs=String(m[1]||""),hhref=attr(hattrs,"href"),htitle=attr(hattrs,"title")||text(m[2]);
    var hseg=html.substring(Math.max(0,m.index-300),Math.min(html.length,m.index+5000));
    add(out,seen,htitle,hhref,hseg);
    if(out.length>=60)break;
}
if(out.length)return out;

/* 3. Regex result-container fallback; avoids dependence on Hiker parseDom selectors. */
var bre=/<(?:li|article|div)\b([^>]*)>([\s\S]*?)<\/(?:li|article|div)>/gi;
while((m=bre.exec(html))!==null){
    var battrs=String(m[1]||""),bcls=attr(battrs,"class"),bid=attr(battrs,"id");
    if(!/(media|result|torrent|search-item|list-item)/i.test(bcls+" "+bid))continue;
    var block=String(m[0]||""),am=/<a\b([^>]*)>([\s\S]*?)<\/a>/gi.exec(block);
    if(!am)continue;
    var ahref=attr(am[1],"href"),atitle=attr(am[1],"title")||text(am[2]);
    if(!atitle||/^(首页|登录|注册|下一页|上一页|更多|搜索)$/i.test(atitle))continue;
    add(out,seen,atitle,ahref,block);
    if(out.length>=60)break;
}
if(out.length)return out;

